/*
 * A338741  When a(n) is odd, a(n) is the number of odd digits present so far
 *          in the sequence, a(n) included.
 * https://oeis.org/A338741
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   a(n) is generated by keeping the next unused even integer and
 *            the count of odd digits that have appeared so far in the
 *            sequence. Let k be the number of odd digits in a(1)…a(n‑1). If
 *            an odd integer o satisfies o = k + (number of odd digits in o)
 *            and o is not larger than the next unused even intege...
 * Range:     u8 n <= 80, u16 n <= 80, u32 n <= 80, u64 n <= 80, u128 n <= 80,
 *            big any n
 * Validated: partial, pass, 80 terms through n = 80 (2026-11-03)
 * Helpers:   mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include "../utils/mem.h"

/* Count the odd decimal digits of x. */
static seq_t count_odd_digits(seq_t x)
{
    seq_t cnt = 0;
    while (x > 0) {
        seq_t d = x % 10;
        if (d & 1u) ++cnt;
        x /= 10;
    }
    return cnt;
}

/* Return the smallest odd integer satisfying
   o = k + count_odd_digits(o), or 0 if none exists. */
static seq_t find_candidate_odd(seq_t k)
{
    seq_t cand = 1;
    for (;;) {
        seq_t d    = count_odd_digits(cand);
        seq_t left = cand - d;
        if (left == k)      return cand;
        if (left >  k)      return 0;   /* no solution for this k */
        cand += 2;                     /* skip to next odd number */
    }
}

seq_t a(idx_t n)
{
    /* Cache for memoisation.  cache[0] holds a(1). */
    static seq_t *cache      = NULL;
    static idx_t cache_size  = 0; /* number of terms stored */
    static idx_t cache_cap   = 0; /* allocated capacity       */
    static seq_t odd_count   = 0; /* total odd digits so far */
    static idx_t evens_used  = 0; /* how many even terms used */

    if (n == 0) return 0;           /* safety, though n≥1 in spec */

    /* Return cached value if already computed. */
    if (n <= cache_size) return cache[n - 1];

    /* Grow the cache if necessary. */
    if (n > cache_cap) {
        idx_t new_cap = cache_cap ? cache_cap << 1 : 128;
        if (new_cap < n) new_cap = n;
        cache = mem_resize(seq_t, cache, (size_t)new_cap);
        cache_cap = new_cap;
    }

    /* Generate terms from cache_size+1 up to n. */
    for (idx_t i = cache_size + 1; i <= n; ++i) {
        seq_t next_even  = (seq_t)(2 * evens_used);
        seq_t cand_odd   = find_candidate_odd(odd_count);
        seq_t val;

        if (cand_odd && cand_odd <= next_even) {
            val = cand_odd;
            odd_count += count_odd_digits(val);
            /* evens_used unchanged */
        } else {
            val = next_even;
            odd_count += count_odd_digits(val);
            ++evens_used;
        }
        cache[i - 1] = val;
    }

    cache_size = n;
    return cache[n - 1];
}
